for (size_t i = start; i < end; ++i) {
    Particle &pi = particles[i];
    if (pi.type == 0) continue;

    std::array<int, 3> coord;
    coord[0] = static_cast<int>(std::floor(pi.pos.x / h));
    coord[1] = static_cast<int>(std::floor(pi.pos.y / h));
    coord[2] = static_cast<int>(std::floor(pi.pos.z / h));

    std::array<int, 3> minCoord = { std::max(0, coord[0] - 1), std::max(0, coord[1] - 1), std::max(0, coord[2] - 1) };
    std::array<int, 3> maxCoord = { std::min(255, coord[0] + 1), std::min(255, coord[1] + 1), std::min(255, coord[2] + 1) };

    pi.pressure = 0.0f;
    pi.density = 0.0f;
    pi.viscosity = { 0.0f, 0.0f, 0.0f };

    for (int z = minCoord[2]; z <= maxCoord[2]; ++z) {
        for (int y = minCoord[1]; y <= maxCoord[1]; ++y) {
            for (int x = minCoord[0]; x <= maxCoord[0]; ++x) {
                uint32_t hash = ((x * 73856093) ^ (y * 19349663) ^ (z * 83492791)) & 0x3FF;
                uint32_t idx = particleTable[hash];
                while (idx != 0xFFFFFFFF) {
                    const Particle &pj = particles[idx];
                    if (pj.type != 0 && idx != i) {
                        float dx = pi.pos.x - pj.pos.x;
                        float dy = pi.pos.y - pj.pos.y;
                        float dz = pi.pos.z - pj.pos.z;
                        float r2 = dx * dx + dy * dy + dz * dz;
                        if (r2 < h2 && r2 > 0.0f) {
                            float r = std::sqrt(r2);
                            float q = 1.0f - r / h;
                            float q2 = q * q;
                            float q3 = q2 * q;
                            pi.density += mass * q3;
                            float pressure = pj.pressure * q3;
                            pi.pressure += pressure;
                            float viscosityCoeff = viscosity * mass * q2 / r;
                            pi.viscosity.x += viscosityCoeff * (pj.vel.x - pi.vel.x);
                            pi.viscosity.y += viscosityCoeff * (pj.vel.y - pi.vel.y);
                            pi.viscosity.z += viscosityCoeff * (pj.vel.z - pi.vel.z);
                        }
                    }
                    idx = pj.next;
                }
            }
        }
    }

    if (pi.density > 0.0f) {
        float invDensity = 1.0f / pi.density;
        pi.pressure *= spikyGrad * invDensity * invDensity;
        pi.viscosity.x *= spikyLap * invDensity;
        pi.viscosity.y *= spikyLap * invDensity;
        pi.viscosity.z *= spikyLap * invDensity;
    } else {
        pi.pressure = 0.0f;
        pi.viscosity = { 0.0f, 0.0f, 0.0f };
    }
}
// END_CODE

